    }
    const result = parseCreatedSplit(
      await client.call(
        "pane.split",
        {
          target_pane_id: request.parent.paneId,
          workspace_id: request.parent.workspaceId,
          cwd: request.context.cwd,
          direction: "right",
          focus: false,
        },
        signal,
      ),
    );
